(23, 'Chemical Process Safety', 'Dr. Ganesh B. Shinde, Dr. Subhash B. Magar, Mr. Zamir K. Deshmukh, Sushant S. Kurhe', '978-93-47597-50-3', '1st Edition', 5, '\"Chemical Process Safety\" is a comprehensive guide to the design and implementation of advanced chemical process safety measures. It covers topics such as hazard identification, risk assessment, safety management systems, and emergency response protocols. This book is an essential resource for chemical engineers, safety professionals, and researchers seeking to deepen their understanding of chemical process safety and their applications in real-world scenarios.', 1237.93, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 280, '2026', '/uploads/books/1784087822956-Chemical Process Safety p1.png', '/uploads/books/1784087822973-Chemical Process Safety p2.png', NULL, '2026-07-15 03:57:02'),
(30, 'Engineering Mathematics', 'Dr.K.Chitra', '978-93-47597-35-0', '1st Edition', 3, 'Engineering Mathematics applies mathematical methods to solve engineering problems. It includes calculus, differential equations, linear algebra, probability, and numerical methods. These tools help model, analyze, and optimize systems in fields like mechanics, electronics, and civil engineering, enabling precise design, prediction, and decision-making in real-world applications.', 1126.00, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 210, '2026', '/uploads/books/1784092474091-Engineering Mathematics P1.png', '/uploads/books/1784092474116-Engineering Mathematics P2.png', NULL, '2026-07-15 05:14:34'),
(31, 'Core Concepts of Civil Engineering', 'Dr. Geena M.G, Mr.B. Deepan Kumar, Mr.E.Santhosh Kumar, Mr.Kannan.S', '978-93-47597-10-7', '1st Edition', 5, 'Core Concepts of Civil Engineering introduce the fundamental principles involved in designing, constructing, and maintaining infrastructure projects. It covers structural analysis, construction materials, surveying, transportation, and environmental engineering for sustainable development.', 1448.00, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 245, '2026', '/uploads/books/1784092811474-Core Concepts of Civil Engineering p1.png', '/uploads/books/1784092811482-Core Concepts of Civil Engineering p2.png', NULL, '2026-07-15 05:20:11'),
(32, 'Artificial Intelligence and Machine Learning', 'B H Vinod Kumar, Mr. Chittaluri Vivek Kumar, Vankdavath Ramu, Shaikh Jakeer', '978-93-47597-19-0', '1st Edition', 5, 'Artificial Intelligence and Machine Learning focus on developing systems that can learn from data and make intelligent decisions. These technologies enable automation, prediction, pattern recognition, and problem-solving across various real-world applications.', 1350.99, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 326, '2026', '/uploads/books/1784092963880-Artificial Intelligence and Machine Learning p1.png', '/uploads/books/1784092963894-Artificial Intelligence and Machine Learning p2.png', NULL, '2026-07-15 05:22:43'),
(33, 'Artificial Intelligence and Machine Learning in Cloud Applications', 'Mrs. Swathi Srikanth Achanur, Mrs. Bhavya Balakrishnan, Mrs. Suma Manjunath N, Mrs. Savitha B, Mrs. Padmavathi B', '978-93-47597-27-5', '1st Edition', 5, 'Artificial Intelligence and Machine Learning in Cloud Applications focus on integrating AI and ML technologies with cloud computing platforms. It enables intelligent data processing, automation, predictive analysis, and scalable smart applications through cloud-based services and infrastructure.', 1013.00, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 188, '2026', '/uploads/books/1784093094928-Artificial Intelligence and Machine Learning in Cloud Application p1.png', '/uploads/books/1784093094937-Artificial Intelligence and Machine Learning in Cloud Applications p2.png', 'https://www.flipkart.com/innovation-management-entrepreneurial-leadership/p/itm0deeb253b982f?pid=9789347597480', '2026-07-15 05:24:54'),
(34, 'Analog Electronics', 'Dr. Ashwini Suresh Relekar, Mr. Sanjyot Shivajirao Patil, Mrs. Vidhulata Abhijeet Jadhav, Mr. Anup Baburao Kumbhar', '978-93-47597-89-3', '1st Edition', 5, 'Analog Electronics deals with electronic circuits that process continuous signals. It covers components such as diodes, transistors, amplifiers, and oscillators used in communication, audio, and signal-processing applications.', 1351.00, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 317, '2026', '/uploads/books/1784093832896-Analog Electronics p1.png', '/uploads/books/1784093832915-Analog Electronics p2.png', NULL, '2026-07-15 05:37:12'),
(35, 'Deep Learning Fundamentals and Applications', 'Mrs.S. Ramalakshmi, Mrs.R.Muthulakshmi, Ms.G. Elakkiyaselvam, Dr.S.Senthil', '978-93-47597-17-6', '1st Edition', 5, 'Deep Learning focuses on neural networks that learn patterns from large datasets. It powers applications like image recognition, speech processing, recommendation systems, healthcare analysis, autonomous vehicles, and natural language processing. Deep learning improves automation, prediction accuracy, and intelligent decision-making, making it a key technology in modern artificial intelligence systems.', 1238.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 266, '2026', '/uploads/books/1784094514470-Deep Learning Fundamentals and Applications-Ramalakshmi-p1.png', '/uploads/books/1784094514490-Deep Learning Fundamentals and Applications-Ramalakshmi-p2.png', NULL, '2026-07-15 05:48:34'),
(36, 'Fundamentals of Biochemistry | Dr.A.Allwyn Sundarraj', 'Dr.A.Allwyn Sundarraj, Nithya Bala Sundari S, Dr.U.S.Rammiya, N Jamunasri, Dr.P.Hema Prabha', '978-93-47597-41-1', '1st Edition', 5, 'Biochemistry explores the molecular basis of life, including proteins, carbohydrates, lipids, enzymes, DNA, and metabolism. It explains how cells obtain energy, grow, communicate, and maintain balance. Understanding biochemical reactions helps in medicine, genetics, nutrition, and biotechnology, forming the foundation for modern biological and health sciences.', 1125.99, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 235, '2026', '/uploads/books/1784094670470-Fundamentals of Biochemistry-Allwyn-p1.png', '/uploads/books/1784094670485-Fundamentals of Biochemistry-Allwyn-p2.png', NULL, '2026-07-15 05:51:10'),
(37, 'Fundamentals of Biochemistry', 'Dr. C. Vigneshwaran, Dr. N. Saravanan, Dr. K. Saranya, Mr. B. Prasanna', '978-93-47597-59-6', '1st Edition', 5, 'Biochemistry explores the molecular basis of life, including proteins, carbohydrates, lipids, enzymes, DNA, and metabolism. It explains how cells obtain energy, grow, communicate, and maintain balance. Understanding biochemical reactions helps in medicine, genetics, nutrition, and biotechnology, forming the foundation for modern biological and health sciences.', 1335.96, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 230, '2026', '/uploads/books/1784095144511-Fundamentals of Biochemistry-Vigneshwaran-p1.png', '/uploads/books/1784095144544-Fundamentals of Biochemistry-Vigneshwaran-p2.png', NULL, '2026-07-15 05:59:04'),
(38, 'Intelligent Automation with Artificial Intelligence and Machine Learning', 'Mrs. Kalpana Chittor S, Mrs.Deepa Desai Ramya P, N Karthik kumar', '978-93-47597-46-6', '1st Edition', 5, 'Intelligent automation combines artificial intelligence and machine learning to automate complex tasks, improve decision-making, increase efficiency, reduce errors, and enable adaptive systems that learn from data across industries and business processes.', 1350.98, 'In Stock', '310 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 326, '2026', '/uploads/books/1784095324297-Intelligent automation with artificial intelligence and machine learning p1.png', '/uploads/books/1784095324322-Intelligent automation with artificial intelligence and machine learning p2.png', 'https://www.flipkart.com/innovation-management-entrepreneurial-leadership/p/itm0deeb253b982f?pid=9789347597480', '2026-07-15 06:02:04'),
(39, 'Innovation Management and Entrepreneurial Leadership', 'Dr. VE. Santhi Shuchi Aggarwal, Dr. Nagendra B M, Balasubramanian A, Aniruth N M', '978-93-47597-48-0', '1st Edition', 5, 'Innovation management and entrepreneurial leadership focus on creating ideas, managing change, fostering creativity, and guiding teams to build sustainable businesses, drive growth, solve problems, and adapt to dynamic market environments effectively.', 1126.00, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 253, '2026', '/uploads/books/1784095470918-Innovation Management p1.png', '/uploads/books/1784095470925-Innovation Management p2.png', 'https://www.flipkart.com/innovation-management-entrepreneurial-leadership/p/itm0deeb253b982f?pid=9789347597480', '2026-07-15 06:04:30'),
(40, 'Edge Computing in IoT Applications', 'Dr.Abul Kashim Md Fujail, Dr.Saptarshi Paul', '978-93-47597-20-6', '1st Edition', 5, 'Edge computing in IoT processes data near devices instead of centralized clouds, reducing latency, saving bandwidth, improving real-time decision-making, enhancing privacy, and enabling efficient, scalable smart systems across industries.', 1125.99, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 266, '2026', '/uploads/books/1784095624790-Edge Computing in Iot Applications p1.png', '/uploads/books/1784095624798-Edge Computing in Iot Applications p2.png', NULL, '2026-07-15 06:07:04'),
(41, 'Mastering Deep Learning Architectures', 'Ms. Kamatchi C, Ms. Anitha R, Mr. Subbarayudu A, Mrs. Kichagari Sruthi, Ms. P. Abirami', '978-93-47597-87-9', '1st Edition', 5, 'Mastering deep learning architectures involves understanding neural networks, CNNs, RNNs, and transformers to build efficient models, improve accuracy, handle complex data, and solve real-world problems in AI applications.', 1126.00, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 265, '2026', '/uploads/books/1784095864132-Mastering Deep Learning Architectures p1.png', '/uploads/books/1784095864150-Mastering Deep Learning Architectures p2.png', '', '2026-07-15 06:11:04'),
(42, 'Fundamentals of Electronics & Communication Systems', 'Dr.Mandeep kaur, Dr. Dipti Bansal', '978-93-47597-78-7', '1st Edition', 5, 'Fundamentals of Electronics & Communication Systems covers electronic components, circuits, signal processing, analog and digital communication, transmission methods, modulation techniques, and system design for efficient information transfer.', 1126.00, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 234, '2026', '/uploads/books/1784106020043-Fundamentals of Electronics & Communication Systems p1.png', '/uploads/books/1784106020097-Fundamentals of Electronics & Communication Systems p2.png', NULL, '2026-07-15 09:00:20'),
(43, 'Corporate Accounting and Reporting', 'Dr S Balakrishnan, Dr M Nirmal Dev, Mrs. B. Sathya Guna, Dr. Srikantalahari Sagi, Dr.R.Aruljothi', '978-93-47597-43-5', '1st Edition', 5, 'Corporate Accounting and Reporting focuses on preparing and presenting financial statements of companies. It covers accounting standards, financial analysis, and reporting practices to ensure accuracy, transparency, and compliance with regulations.', 1463.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 355, '2026', '/uploads/books/1784106188741-Corporate Accounting and Reporting p1.png', '/uploads/books/1784106188753-Corporate Accounting and Reporting p2.png', 'https://www.flipkart.com/corporate-accounting-reporting/p/itmbd727ee5cfe7b?pid=9789347597435', '2026-07-15 09:03:08'),
(44, 'Ai-Driven-Cybersecurity-(Threat Detection And Response)', 'Tina Victoria A, Dr. Anant D. Chinchure, Er.Apoorva K A, Mohammad Rahmat Ali', '978-93-47597-42-8', '1st Edition', 5, 'AI-driven cybersecurity uses artificial intelligence to detect threats, analyze patterns, prevent attacks, and respond quickly, improving system security, reducing risks, and enhancing protection against evolving cyber threats in real time.', 1351.00, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 323, '2026', '/uploads/books/1784519681742-Ai-Driven Cybersecurity p1.png', '/uploads/books/1784519681777-Ai-Driven Cybersecurity P2.png', 'https://www.flipkart.com/ai-driven-cybersecurity-threat-detection-response/p/itm7ca0051607c7c?pid=9789347597428', '2026-07-20 03:54:41'),
(45, 'Machine Learning Fundamentals and Techniques', 'V.G.Thamarai Selvi, SreeramYamini, S.Karal Marx, Dr.N.Gayathri Devi', '978-93-47597-05-3', '1st Edition', 5, 'Machine Learning (ML) is a branch of artificial intelligence that enables systems to learn from data, identify patterns, and make decisions with minimal human intervention. It has become a fundamental technology in various fields, including healthcare, finance, and automation.', 1126.00, 'In Stock', '270 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 215, '2026', '/uploads/books/1784519815280-Machine Learning Fundamentals and Techniques P1.png', '/uploads/books/1784519815296-Machine Learning Fundamentals and Techniques P2.png', 'https://www.flipkart.com/machine-learning-fundamentals-techniques/p/itmfe77507388e69?pid=9789347597053', '2026-07-20 03:56:55'),
(46, 'Intellectual Property Rights', 'Dr.John de britto, c Dr.R.Umamageswari, Dr.J.Vijay anand, Dr.D.Lakshmi', '978-93-47597-81-7', '1st Edition', 5, 'Intellectual Property Rights (IPR) protect creations like inventions, designs, and artistic works, granting creators legal ownership, exclusive usage rights, and incentives for innovation, creativity, and economic growth while preventing unauthorized use.', 1126.00, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 229, '2026', '/uploads/books/1784519974822-Intellectual Property Rights p1.png', '/uploads/books/1784519974853-Intellectual Property Rights p2.png', NULL, '2026-07-20 03:59:34'),
(47, 'The Blue Economy of India: The Road to Sustainable Development and Prosperity', 'Dr. Pranathi A V', '978-93-47597-13-8', '1st Edition', 5, 'The Blue Economy focuses on the sustainable use of ocean resources to support economic growth, improve livelihoods, and maintain the health of marine ecosystems. In India, it plays an important role in sectors such as fisheries, maritime trade, tourism, and renewable ocean energy.', 1351.00, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 207, '2026', '/uploads/books/1784520098430-The Blue Economy of India p1.png', '/uploads/books/1784520098447-The Blue Economy of India p2.png', NULL, '2026-07-20 04:01:38'),
(48, 'Python Programming Essential', 'Dr Adilakshmamma T, Bharani Lokesh T', '978-93-47597-00-8', '1st Edition', 5, 'Python Programming Essentials focuses on the basic concepts of the Python programming language, including variables, data types, control statements, functions, and data structures. Python is known for its simple syntax and readability, making it easy for beginners to learn.', 1126.00, 'In Stock', '220 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 168, '2026', '/uploads/books/1784520208146-Python-Programming-Essentials-p1.png', '/uploads/books/1784520208163-Python-Programming-Essentials-p2.png', NULL, '2026-07-20 04:03:28'),
(49, 'Principles of Research Design with Qualitative, Quantitative, and Mixed Approaches', 'Dr. A. Saravanan, Dr. Chitra Gupta, Dr. Neha Shroff, Dr. SavitaTrivedi', '978-93-47597-69-5', '1st Edition', 5, 'Research design is the plan used to collect, analyze, and interpret data in a study.Qualitative research focuses on opinions and experiences, while quantitative research uses numerical data and statistical analysis.', 1126.00, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 207, '2026', '/uploads/books/1784520368474-Principles-of-Research-Design-with-Qualitative,Quantitative-and-Mixed-Approaches.p1.png', '/uploads/books/1784520368486-Principles-of-Research-Design-with-Qualitative,Quantitative-and-Mixed-Approaches.p2.png', 'https://www.flipkart.com/principles-research-design-qualitative-quantitative-mixed-approaches/p/itmc5ac3a6eba395?pid=9789347597695', '2026-07-20 04:06:08'),
(50, 'Next-Generation Wireless Communication', 'Dr.Kalyana Chakravarthy Chilukur,i Dr. R. Karthikeyan, Dr. Nune Sreenivas, Mrs.R.Nirmala', '978-93-47597-86-2', '1st Edition', 5, 'Next-Generation Wireless Communication refers to advanced technologies like 5G and future networks that provide faster and more reliable wireless connectivity.It offers high data speed, low latency, and the ability to connect many devices simultaneously.', 1351.00, 'In Stock', '220 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 168, '2026', '/uploads/books/1784520484019-Next Generation Wireless Communications p1.png', '/uploads/books/1784520484031-Next Generation Wireless Communications p2.png', 'https://www.flipkart.com/next-generation-wireless-communication/p/itme8317d8e2ac8c?pid=9789347597862', '2026-07-20 04:08:04'),
(51, 'Data structures: concepts and implementations', 'Dr Adilakshmamma T, Bharani Lokesh T', '978-93-47597-97-8', '1st Edition', 5, 'This topic explains the basic concepts of data structures and how they are implemented in programming. It covers structures like arrays, stacks, queues, linked lists, trees, and graphs, helping organize and manage data efficiently for problem solving.', 1125.99, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 207, '2026', '/uploads/books/1784520600724-Data Structures Concepts and Implementations p1.png', '/uploads/books/1784520600736-Data Structures Concepts and Implementations p2.png', NULL, '2026-07-20 04:10:00'),
(52, 'Whispers of Night', 'Gopinath Sampath', '978-93-47597-26-8', '1st Edition', 5, 'Whispers of Night describes the calm and mysterious atmosphere of the night. It highlights the quiet sounds, gentle breeze, and peaceful surroundings that appear after sunset, creating a sense of beauty, reflection, and imagination in the darkness.', 787.99, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 76, '2026', '/uploads/books/1784520746329-Whispers of Night p1.png', '/uploads/books/1784520746339-Whispers of Night p2.png', NULL, '2026-07-20 04:12:26'),
(53, 'Industry 4.0 and Smart Manufacturing', 'Dr kunduru srinivasulu reddy, Dr krishnamohan reddy kunduru', '978-93-47597-45-9', '1st Edition', 5, 'Industry 4.0 and Smart Manufacturing focus on the use of advanced technologies like IoT, artificial intelligence, and automation in manufacturing. These technologies help create smart factories that improve efficiency, productivity, and real-time decision-making in industrial processes.', 1463.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 361, '2026', '/uploads/books/1784521026853-Industry 4.0 and Smart Manufacturing p1.png', '/uploads/books/1784521026868-Industry 4.0 and Smart Manufacturing p2.png', 'https://www.flipkart.com/industry-4-0-smart-manufacturing/p/itm656dcd3152fe1?pid=9789347597459', '2026-07-20 04:17:06'),
(54, 'Foundations of AI and Machine Learning for Engineers', 'Dr. Karamath Ateeq, Mr. Gollapalli Ramesh, Dr. G. Nandha Kishore Kumar, Surjya Narayan Sahoo', '978-93-47597-83-1', '1st Edition', 5, 'Foundations of AI and Machine Learning for Engineers introduces the basic concepts of artificial intelligence and machine learning used in engineering. It covers algorithms, data analysis, and model development to solve real-world engineering problems efficiently.', 1351.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 326, '2026', '/uploads/books/1784521163689-Foundations of AI and Machine Learning for Engineers p1.png', '/uploads/books/1784521163713-Foundations of AI and Machine Learning for Engineers p2.png', 'https://www.flipkart.com/foundations-ai-machine-learning-engineers/p/itm4e78cbd674a52?pid=9789347597831', '2026-07-20 04:19:23'),
(55, 'Financial Analytics with Excel and R Essential Tools', 'Dr.S.Janeefa Priya', '978-93-47597-03-9', '1st Edition', 5, 'Financial Analytics with Excel and R focuses on using analytical tools to analyze financial data and support decision-making. It teaches how Excel and R can be used for data analysis, forecasting, and financial modeling to improve business and investment strategies.', 1351.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 317, '2026', '/uploads/books/1784521295772-Financial-Analytics-with-Excel-and-R-Essential-Tools-p1.png', '/uploads/books/1784521295783-Financial-Analytics-with-Excel-and-R-Essential-Tools-p2.png', NULL, '2026-07-20 04:21:35'),
(56, 'Deep Learning Fundamentals and Applications', 'Omesh Wadhwani, Prof.Dhirajkumar Gupta, Dr. Reema Roychaudharyr, Ayaz Ahmed Khan', '978-93-47597-07-7', '1st Edition', 5, 'Deep Learning Fundamentals and Applications presents the core principles of deep neural networks, including backpropagation, CNNs, RNNs, and optimization methods. It explores applications in computer vision, natural language processing, speech recognition, and healthcare analytics. Combining theory with practical implementation strategies, the book equips readers to build, train, and deploy effective deep learning models.\r\n\r\n', 1013.00, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 168, '2026', '/uploads/books/1784521459038-Deep Learning Fundamentals Omesh p1.png', '/uploads/books/1784521459049-Deep Learning Fundamentals Omesh p2.png', 'https://www.flipkart.com/deep-learning-fundamentals-applications/p/itmdf8ac6ec73891?pid=9789347597077', '2026-07-20 04:24:19'),
(57, 'Engineering Chemistry: Concepts and Practices', 'Mr. Pankaj Javrilal Bafna', '978-93-47597-84-8', '1st Edition', 5, 'Engineering Chemistry: Concepts and Practices provides a comprehensive understanding of chemical principles applied in engineering fields. It covers atomic structure, thermodynamics, electrochemistry, corrosion control, polymers, fuels, lubricants, water treatment, and nanotechnology. The book combines theoretical foundations with industrial applications to help students grasp material behavior and chemical processes in engineering environments.\n\n', 1126.00, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 280, '2026', '/uploads/books/1784521592509-Engineering Chemistry Pankaj p1.png', '/uploads/books/1784521592523-Engineering Chemistry Pankaj p2.png', NULL, '2026-07-20 04:26:32'),
(58, 'Artificial Intelligence with the HR Analytics', 'Dr. Prabakaran Paranthaman, Dr.K.Vijayalakshmi', '978-93-47597-73-2', '1st Edition', 5, 'Artificial Intelligence with HR Analytics explores the integration of AI technologies into human resource management practices. It covers talent acquisition, predictive workforce analytics, performance evaluation, employee engagement, and retention strategies. The book emphasizes data-driven decision-making, automation tools, ethical considerations, and practical frameworks to enhance organizational effectiveness and strategic HR management.', 1126.00, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 205, '2026', '/uploads/books/1784521765382-Artificial Intelligence with the HR Analytics p1.png', '/uploads/books/1784521765401-Artificial Intelligence with the HR Analytics p2.png', NULL, '2026-07-20 04:29:25'),
(59, 'Corporate Accounting Principles and Practices', 'Dr. V. Archana Binju', '978-93-47597-37-4', '1st Edition', 5, 'Corporate Accounting: Principles and Practices presents a comprehensive study of corporate financial accounting, focusing on accounting standards, company law provisions, and financial reporting requirements. It covers share capital, debentures, dividends, mergers, acquisitions, and consolidation of accounts. The book blends conceptual clarity with practical problem-solving to strengthen analytical and reporting skills.\r\n\r\n', 1447.99, 'In Stock', '280 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 355, '2026', '/uploads/books/1784521891233-Corporate Accounting Archana p1.png', '/uploads/books/1784521891250-Corporate Accounting Archana p2.png', NULL, '2026-07-20 04:31:31'),
(60, 'Engineering Chemistry: Concepts and Practices', 'Mrs. Neyyala Chaitanya, Mr Chandrasekhar Tarini', '978-93-47597-54-1', '1st Edition', 5, 'Engineering Chemistry: Concepts and Practices covers fundamental chemical principles relevant to engineering applications. It explores atomic structure, chemical bonding, thermodynamics, electrochemistry, corrosion, polymers, fuels, water treatment, and nanomaterials. The book integrates theory with practical industrial examples, enabling students to understand chemical processes and material behavior in engineering contexts.\n\n', 1448.00, 'In Stock', '280 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 282, '2026', '/uploads/books/1784522069415-Engineering Chemistry Neyyala p1.png', '/uploads/books/1784522069433-Engineering Chemistry Neyyala p2.png', NULL, '2026-07-20 04:34:29'),
(61, 'Developmental Biology: Essential Concepts', 'Dr.Padmapriya.V, Dr.Sujithra.K, Ms.Mahalakshmi.M, Dr.Sivasankaran Ramarajan, Dr.Mythili.K', '978-93-47597-61-9', '1st Edition', 5, 'Developmental Biology: Essential Concepts explores the fundamental processes that govern organismal growth and development. It covers cell differentiation, gene regulation, embryogenesis, morphogenesis, stem cells, and signaling pathways. The book integrates molecular, genetic, and evolutionary perspectives to explain how complex organisms form, providing a clear foundation for advanced biological studies.\n\n', 1126.00, 'In Stock', '280 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 197, '2026', '/uploads/books/1784522181321-Developmental Biology Padmapriya p1.png', '/uploads/books/1784522181334-Developmental Biology Padmapriya p2.png', NULL, '2026-07-20 04:36:21'),
(62, 'Basic Electrical Engineering', 'Prof.C.Suresh,M.E, Prof.M.Balasubramanian, M.E, Prof.M.Chandrasekaran, M.E, Prof.T.Paavendhan, M.Tech, Prof.G.Gopika, M.E', '978-93-47597-60-2', '1st Edition', 5, 'Basic Electrical Engineering introduces fundamental concepts of electrical circuits, voltage, current, resistance, power, and energy. It covers AC and DC circuits, electrical machines, transformers, measurement instruments, and safety practices. The book blends theoretical principles with practical applications, providing a strong foundation for students and beginners in electrical and electronics engineering.\n\n', 1125.99, 'In Stock', '280 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 220, '2026', '/uploads/books/1784522345275-Basic Electrical Engineering Suresh p1.png', '/uploads/books/1784522345287-Basic Electrical Engineering Suresh p2.png', NULL, '2026-07-20 04:39:05'),
(63, 'Fundamentals of Artificial Intelligence', 'Priyadharsini', '978-93-47597-68-8', '1st Edition', 5, 'Fundamentals of Artificial Intelligence introduces the core concepts, history, and principles of AI. It covers problem-solving methods, search algorithms, knowledge representation, machine learning basics, neural networks, and ethical considerations. The book provides a balanced blend of theory and practical examples to help readers understand and apply artificial intelligence techniques effectively.\n\n', 1126.00, 'In Stock', '280 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 224, '2026', '/uploads/books/1784522525597-Fundamentals of Artificial Intelligence Priyadarsini p1.png', '/uploads/books/1784522525609-Fundamentals of Artificial Intelligence Priyadarsini p2.png', NULL, '2026-07-20 04:42:05'),
(64, 'Communicative English for Interviews', 'Sivaprasad Mopuri, Shaik Mohammad Arshad', '978-93-47597-64-0', '1st Edition', 5, 'Communicative English for Interviews: Mastering Language of Success focuses on developing effective spoken and written English skills for job interviews. It covers grammar essentials, vocabulary building, body language, confidence enhancement, group discussions, and common interview questions. The book provides practical exercises and real-life scenarios to help candidates communicate clearly and professionally.\n\n', 1013.00, 'In Stock', '190 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 157, '2026', '/uploads/books/1784528372932-Communicative english for interviews Sivaprasad p1.png', '/uploads/books/1784528372949-Communicative english for interviews Sivaprasad p2.png', NULL, '2026-07-20 06:19:32'),
(65, 'Marketing Management and Consumer Behaviour', 'Dr.Selvadurgadevi, Mrs.P.Anu Priya Lakshmi , Dr.V. Archana Binju , Dr.M.Radhika, Asha A', '978-93-47597-80-0', '1st Edition', 5, 'Marketing Management and Consumer Behaviour explores strategic marketing planning, market segmentation, branding, pricing, promotion, and distribution strategies. It examines psychological, social, and cultural factors influencing consumer decision-making. The book integrates marketing theories with real-world case studies to help readers understand customer needs, build strong brands, and develop competitive market strategies.\r\n\r\n', 1126.00, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 185, '2026', '/uploads/books/1784528629799-Marketing Management and Consumer Behaviour Selvadurgadevi p1.png', '/uploads/books/1784528629809-Marketing Management and Consumer Behaviour Selvadurgadevi p2.png', NULL, '2026-07-20 06:23:49'),
(66, 'Deep Learning Fundamentals and Applications', 'Dr. Sweta Ramendra Kumar, Dr. Upasana Subhashchandra Mehta, Prof. Anshikakumari Jayshiv Yadav, Prof. Simpi Shmabhu Singh, Prof. Roshan Pramod Dixit', '978-93-47597-51-0', '1st Edition', 5, 'Deep Learning Fundamentals and Applications introduces core concepts of neural networks, backpropagation, convolutional and recurrent models, and optimization techniques. It explores practical applications in computer vision, natural language processing, speech recognition, and healthcare. The book combines theory with hands-on examples, enabling readers to design, train, and deploy deep learning models effectively.\r\n\r\n', 1013.00, 'In Stock', '220 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 168, '2026', '/uploads/books/1784529254977-Deep Learning Fundamentals and Applications p1.png', '/uploads/books/1784529254990-Deep Learning Fundamentals and Applications p2.png', 'https://www.flipkart.com/deep-learning-fundamentals-applications/p/itm2bbea35b30a49?pid=9789347597510', '2026-07-20 06:34:15'),
(67, 'Data and Information Security', 'Dr. R. Priya', '978-81-995247-8-1', '1st Edition', 5, 'Data and information security protects data from unauthorized access, misuse, alteration, or loss. It uses policies, technologies, and practices like encryption, access control, and backups to ensure confidentiality, integrity, and availability of information in digital and physical systems.\n\n', 1462.95, 'In Stock', '500 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 364, '2026', '/uploads/books/1784529383114-Data and Information Security p1.png', '/uploads/books/1784529383146-Data and Information Security p2.png', 'https://www.flipkart.com/data-information-security/p/itmcd6738b7d6ca8?pid=9788199524781', '2026-07-20 06:36:23'),
(68, 'Macro Economics II', 'Dr. V. Bala Ruby', '978-81-995247-9-8', '1st Edition', 5, 'Macroeconomics II studies short- and long-run economic fluctuations, focusing on output, inflation, and employment. It analyzes aggregate demand and supply, IS–LM and open-economy models, economic growth, and business cycles. The course evaluates monetary and fiscal policy, expectations, and shocks, emphasizing how policy choices affect macroeconomic stability and long-term development using theory, data, and models for real-world policy analysis applications worldwide.\n\n', 1238.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 250, '2026', '/uploads/books/1784529531592-Macro-Economics-2-p1.png', '/uploads/books/1784529531603-Macro-Economics-2-p2.png', NULL, '2026-07-20 06:38:51'),
(69, 'Mastering Machine Learning with Python: Practical Tips and Techniques', 'Ms. Vaishnavi Nampally, Dr. Panjala Mounika, Prof. G. Jayasree, Sr. Prof. N. CH. Bhatracharyulu', '978-81-995247-6-7', '1st Edition', 5, 'This guide explores practical ways to master machine learning using Python, covering essential libraries, data preprocessing, model selection, training, evaluation, and optimization techniques. It emphasizes hands-on practice, real-world projects, and best practices to build accurate, efficient, and scalable machine learning solutions.\n\n', 1126.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 250, '2026', '/uploads/books/1784529690833-Mastering Machine Learning with Python-Vaishnavi p1.png', '/uploads/books/1784529690845-Mastering Machine Learning with Python-Vaishnavi p2.png', NULL, '2026-07-20 06:41:30'),
(70, 'Research Methodology : Tools and techniques', 'Dr. N Megalai, Dr. Srikantalahari Sagi, Dr.Aishwarya N, Mr. Anirudh N M', '978-93-47597-99-2', '1st Edition', 5, 'Research methodology covers systematic tools and techniques used to plan, conduct, and analyze research. It includes research design, data collection methods, sampling, measurement, and statistical analysis. These approaches ensure validity, reliability, and accuracy, helping researchers draw meaningful conclusions and solve problems effectively.\r\n\r\n', 1125.93, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 249, '2026', '/uploads/books/1784529820913-Research-Methodology-Tools-and-techniques-Megalai-p1.png', '/uploads/books/1784529820932-Research-Methodology-Tools-and-techniques-Megalai-p2.png', 'https://www.flipkart.com/research-methodology-tools-techniques/p/itm5b3bd85046e1a?pid=9789347597992', '2026-07-20 06:43:40'),
(71, 'Essentials of Biochemistry', 'Dr. A. Sheela, Ms. L. Kanchana, Dr. G. Gomathy', '978-81-995247-4-3', '1st Edition', 4, 'Essentials of Biochemistry explains the fundamental principles of biochemistry, focusing on the structure and function of biomolecules, enzymes, metabolism, and energy transformations. It highlights the molecular basis of biological processes, linking chemical concepts to physiological functions, and provides a clear foundation for understanding health, disease, and life at the cellular level.\n\n', 1126.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 244, '2026', '/uploads/books/1784530074089-Essentials of Biochemistry p1.png', '/uploads/books/1784530074105-Essentials of Biochemistry p2.png', NULL, '2026-07-20 06:47:54'),
(72, 'Advance R programming', 'Dr. Ameen Saheb Shaik, Ms. Vaishnavi Nampally, Prof. G. Jayasree, Sr. Prof. N. Ch. Bhatra Charyulu', '978-81-995247-7-4', '1st Edition', 5, 'Advanced R Programming focuses on writing efficient, scalable, and professional R code. It covers advanced data structures, functional programming, environments, object-oriented programming (S3/S4/R6), performance optimization, memory management, debugging, and package development. It helps users build robust data analysis workflows and high-performance statistical applications.\r\n\r\n', 1126.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 243, '2026', '/uploads/books/1784530248290-Advance R programming Ameen p1.png', '/uploads/books/1784530248302-Advance R programming  Ameen p2.png', NULL, '2026-07-20 06:50:48'),
(73, 'R programming', 'Ms. Vaishnavi Nampally, Dr. Ameen Saheb Shaik, Prof. G. Jayasree, Sr. Prof. N. Ch. Bhatra Charyulu', '978-81-995247-0-5', '1st Edition', 5, 'R Programming is a powerful open-source language mainly used for statistical computing, data analysis, and data visualization. It provides a wide range of packages for machine learning, data mining, and scientific research. R is widely used in academics, business analytics, and research for handling large datasets and creating meaningful insights.\n\n', 1126.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 233, '2026', '/uploads/books/1784530420610-R programming  Vaishnavi p1.png', '/uploads/books/1784530420620-R programming  Vaishnavi p2.png', NULL, '2026-07-20 06:53:40'),
(74, 'Biomedical Signal Processing', 'G. Karthigai Priya, Dr. D. Sunderlin Shibu, G. mahanram, Ms. Bhuvaneswari M', '978-93-47597-30-5', '1st Edition', 5, 'Biomedical Signal Processing deals with the analysis and interpretation of biological signals such as ECG, EEG, and EMG using digital and statistical techniques. It helps in noise removal, feature extraction, and diagnosis of medical conditions, enabling accurate monitoring and improved healthcare technologies.\n\n', 1238.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 275, '2026', '/uploads/books/1784530561420-Biomedical Signal Processing p1.png', '/uploads/books/1784530561430-Biomedical Signal Processing p2.png', NULL, '2026-07-20 06:56:01'),
(75, 'Digital Signal Processing: Principles and Applications', 'Dr. Nanda Kishor S Mr. G Vijaya Kiran, Mr. K S Raghavendra Reddy, Mrs. Kumari Kavitha Donthala, Dr. G. N. Kodandaramaiah', '978-93-47597-28-2', '1st Edition', 5, 'Digital Signal Processing (DSP) focuses on the analysis and manipulation of signals in digital form using mathematical algorithms. It involves sampling, filtering, compression, and transformation of signals to improve quality and extract useful information. DSP is widely applied in communications, audio and image processing, biomedical systems, radar, and control systems, enabling efficient, accurate, and reliable processing of real-world signals in modern technology.\n\n', 1126.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 203, '2026', '/uploads/books/1784530875920-Digital Signal Processing Principles and Applications p1.png', '/uploads/books/1784530875928-Digital Marketing Strategies and Tools Swathini p2.png', NULL, '2026-07-20 07:01:15'),
(76, 'Foundations of Quantum Computing', 'Dr. Nanda Kishor S, Mr. I. C. Narasimha, Mr. Jayasimha Thummala, Dr. P. Ajay Kumar Reddy', '978-93-47597-06-0', '1st Edition', 5, 'Foundations of Quantum Computing explores computation based on quantum mechanics principles such as superposition, entanglement, and interference. It introduces qubits, quantum gates, and quantum algorithms that can solve certain problems faster than classical computers. This field forms the basis for advanced technologies in cryptography, optimization, simulation, and secure communication.\n\n', 1126.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 216, '2026', '/uploads/books/1784531285794-Foundations of Quantum Computing  Nanda p1.png', '/uploads/books/1784531285809-Foundations of Quantum Computing  Nanda p2.png', NULL, '2026-07-20 07:08:05'),
(77, 'Foundations of Quantum Computing', 'G. Gomathi, S. Divya, S. V. Priyadarshini, Mrs. Vinodha E', '978-93-47597-04-6', '1st Edition', 5, 'Foundations of quantum computing introduces computation based on quantum mechanics, using qubits instead of classical bits. It explains superposition, entanglement, and quantum interference as core principles. The subject covers quantum gates, circuits, and algorithms, highlighting how quantum computers can solve certain complex problems more efficiently than classical systems.', 1126.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 215, '2026', '/uploads/books/1784531431666-Foundations of Quantum Computing Gomathi p1.png', '/uploads/books/1784531431676-Foundations of Quantum Computing Gomathi p2.png', NULL, '2026-07-20 07:10:31'),
(78, 'Foundations of Quantum Computing', 'Dr. S. Bharani Sethupandian, Mr. B. Vinod Kumar, Mr.Vankdavath Ramu, Mr. Chittaluri Vivek Kumar', '978-93-47597-38-1', '1st Edition', 5, 'Foundations of quantum computing introduces computation based on quantum mechanics, using qubits instead of classical bits. It explains superposition, entanglement, and quantum interference as core principles. The subject covers quantum gates, circuits, and algorithms, highlighting how quantum computers can solve certain complex problems more efficiently than classical systems.\n\n', 1126.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 216, '2026', '/uploads/books/1784531546671-Foundations of Quantum Computing Bharani p1.png', '/uploads/books/1784531546684-Foundations of Quantum Computing Bharani p2.png', NULL, '2026-07-20 07:12:26'),
(79, 'Research Methodology : Tools and techniques', 'Ms. Gomathi A', '978-93-47597-25-1', '1st Edition', 5, 'Research methodology covers systematic tools and techniques used to plan, conduct, and analyze research. It includes research design, data collection methods, sampling, measurement, and statistical analysis. These approaches ensure validity, reliability, and accuracy, helping researchers draw meaningful conclusions and solve problems effectively.\n\n', 1125.99, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 250, '2026', '/uploads/books/1784536448672-Research Methodology Tools and Techniques Gomathi p1.png', '/uploads/books/1784536448684-Research Methodology Tools and Techniques Gomathi p2.png', NULL, '2026-07-20 08:34:08'),
(80, 'Deep Learning Techniques', 'Dr. Deshmukh Sushant Diwakarrao', '978-81-995247-1-2', '1st Edition', 5, 'Deep learning techniques use multilayer neural networks to automatically learn features from large datasets. Key techniques include convolutional neural networks for image processing, recurrent and LSTM networks for sequence data, transformers for attention-based learning, and autoencoders for representation learning. These methods power applications such as vision, speech recognition, natural language processing, and autonomous systems.\n\n', 1013.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 164, '2026', '/uploads/books/1784536559419-Deep Learning Techniques  p1.png', '/uploads/books/1784536559429-Deep Learning Techniques  p2.png', NULL, '2026-07-20 08:35:59'),
(81, 'Talent Acquisition Excellence: Modern Hiring and Retention Strategies', 'Mr. Sharathchandra Kamath K', '978-93-47597-31-2', '1st Edition', 4, 'Talent acquisition excellence focuses on attracting, selecting, and retaining skilled employees through data-driven recruitment, employer branding, and inclusive hiring practices. Modern strategies emphasize AI-assisted screening, candidate experience, continuous learning, competitive compensation, and strong organizational culture to improve retention, engagement, and long-term workforce performance.\n\n', 1238.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 270, '2026', '/uploads/books/1784545655403-Talent Acquisition Excellence p1.png', '/uploads/books/1784545655417-Talent Acquisition Excellence p2.png', NULL, '2026-07-20 11:07:35'),
(82, 'Principles of Sports Training and Performance', 'Dr.S.Ramesh Kannan', '978-93-47597-96-1', '1st Edition', 4, 'Principles of sports training and performance explain how athletes improve fitness, skill, and results through systematic training. Key concepts include overload, specificity, progression, recovery, and periodization. The subject also covers biomechanics, physiology, nutrition, psychology, and performance analysis to optimize athletic development, prevent injury, and achieve peak competitive performance.\n\n', 1351.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 315, '2026', '/uploads/books/1784545994962-Principles of Sports Training and Performance p1.png', '/uploads/books/1784545994982-Principles of Sports Training and Performance p2.png', NULL, '2026-07-20 11:13:15'),
(83, 'Research Methodology', 'Mr. Rakesh B. Patil, Mr. Pramod S. Sonawane, Dr. Abhijeet B. Pawar, Mr. Sachin R. Bhangare', '978-81-995247-2-9', '1st Edition', 5, 'Research methodology explains the systematic process of investigating problems to generate reliable knowledge. It covers research design, qualitative and quantitative approaches, sampling, data collection, hypothesis testing, and analysis techniques. The subject emphasizes ethics, validity, reliability, and proper interpretation of results, enabling researchers to draw meaningful conclusions and contribute effectively to academic and practical fields.', 1126.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 249, '2026', '/uploads/books/1784546942264-Research Methodology Rakesh p1.png', '/uploads/books/1784546942278-Research Methodology Rakesh p2.png', NULL, '2026-07-20 11:29:02'),
(84, 'Digital Marketing', 'Dr.R.Marie Sheila, Dr.S.Subathra', '978-93-47597-02-2', '1st Edition', 5, 'Digital marketing involves promoting products and services through online channels such as search engines, social media, email, and websites. It focuses on targeting specific audiences, analyzing data, and optimizing campaigns to increase brand awareness, customer engagement, leads, and sales in a cost-effective, measurable, and scalable way.\n\n', 1013.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 199, '2026', '/uploads/books/1784547121459-Digital-Marketing-Marie-p1.png', '/uploads/books/1784547121482-Digital-Marketing-Marie-p2.png', NULL, '2026-07-20 11:32:01'),
(85, 'Fundamentals of Internet of Things', 'S. Anitha, Dr. A. Nallathambi, P. Caroline Priyanka Evelyne, A. Jenifer Nirosha', '978-93-47597-11-4', '1st Edition', 5, 'The Fundamentals of Internet of Things (IoT) focus on connecting physical devices embedded with sensors, software, and network connectivity to collect and exchange data. IoT systems integrate hardware, communication protocols, cloud platforms, and analytics to enable automation, real-time monitoring, smart decision-making, and improved efficiency across applications such as smart homes, healthcare, industry, and agriculture.\n\n', 1350.99, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 306, '2026', '/uploads/books/1784547254876-Fundamentals of Internet of Things p1.png', '/uploads/books/1784547254886-Fundamentals of Internet of Things p2.png', NULL, '2026-07-20 11:34:14'),
(86, 'Transmission Lines and Magnetic Fields', 'Mrs. K.Kalpana, Mrs.N.Angalaeswari, Mrs. L. Ramya, Mrs. Gayathri D', '978-93-47597-01-5', '1st Edition', 5, 'Transmission lines are specialized conductors used to carry electrical signals or power efficiently over distances, characterized by parameters such as resistance, inductance, capacitance, and conductance. Magnetic fields arise around current-carrying conductors and influence signal propagation. Understanding transmission line behavior and associated magnetic fields is essential for analyzing signal integrity, power transfer, electromagnetic interference, and high-frequency communication systems.\n\n', 1238.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 235, '2026', '/uploads/books/1784547373267-Transmission Lines and Magnetic Fields p1.png', '/uploads/books/1784547373290-Transmission Lines and Magnetic Fields p2.png', NULL, '2026-07-20 11:36:13'),
(87, 'Digital Signal Processing', 'Dr.M.Seema, P.Jamuna Rani, Dr.C.Sathish Kumar, Dr. N. Rajeswari', '978-93-47597-39-8', '1st Edition', 5, 'Digital Signal Processing (DSP) involves the analysis, modification, and synthesis of signals using digital techniques. It focuses on converting analog signals into digital form and applying algorithms such as filtering, sampling, Fourier transforms, and spectral analysis. DSP is widely used in audio, image processing, communications, biomedical systems, and control applications to improve signal quality, efficiency, and reliability.', 1126.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 207, '2026', '/uploads/books/1784548440691-Digital Signal Processing p1.png', '/uploads/books/1784548440707-Digital Signal Processing p2.png', NULL, '2026-07-20 11:54:00'),
(88, 'HR Analytics', 'Dr. M. Mahalakshmi, Dr. E. Dhowbika Begum', '978-81-995247-5-0', '1st Edition', 5, 'HR Analytics uses data, statistical methods, and technology to analyze workforce information and support human resource decision-making. It helps organizations measure recruitment effectiveness, employee performance, engagement, retention, and training outcomes. By transforming HR data into insights, HR Analytics improves strategic planning, talent management, productivity, and overall organizational performance.\n\n', 1237.99, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 257, '2026', '/uploads/books/1784548591743-HR Analytics p1.png', '/uploads/books/1784548591751-HR Analytics p2.png', NULL, '2026-07-20 11:56:31');
INSERT INTO `books` (`id`, `title`, `authors`, `isbn`, `edition`, `ratings`, `about`, `price`, `status`, `weight`, `binding`, `dimensions`, `language`, `format`, `pages`, `copyright`, `cover1`, `cover2`, `flipkart`, `created_at`) VALUES
(89, 'Textile Processing and Finishing Techniques', 'Dr. S.Divya, Dr. K.S.Saravanya', '978-93-47597-63-3', '1st Edition', 5, 'Textile processing and finishing techniques involve converting raw fibers into usable fabrics with desired properties. Key stages include pretreatment processes like desizing, scouring, and bleaching; coloration through dyeing and printing; and finishing methods such as softening, wrinkle resistance, waterproofing, and flame retardancy. These techniques enhance fabric appearance, comfort, durability, and functional performance.\n\n', 1351.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 302, '2026', '/uploads/books/1784548982409-Textile Processing and Finishing Techniques p1.png', '/uploads/books/1784548982420-Textile Processing and Finishing Techniques p2.png', NULL, '2026-07-20 12:03:02'),
(90, 'Basic Electrical Engineering', 'Dr. Sulake Nagaraja Rao, Dr. Veerabhadra, Manjunatha Budagavi Matam, Suresh Kumar Anisetty', '978-93-47597-58-9', '1st Edition', 5, 'Basic Electrical Engineering covers fundamental concepts of electricity and electrical systems. It includes the study of electric circuits, Ohm’s law, Kirchhoff’s laws, AC and DC circuits, transformers, electrical machines, and measuring instruments. The subject provides a foundation for understanding power generation, transmission, utilization, and the operation of electrical and electronic devices.\r\n\r\n', 1238.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 264, '2026', '/uploads/books/1784549106702-Basic Electrical Engineering p1.png', '/uploads/books/1784549106714-Basic Electrical Engineering p2.png', 'https://www.flipkart.com/basic-electrical-engineering/p/itmcda84de11f7bd?pid=9789347597589', '2026-07-20 12:05:06'),
(91, 'Digital Marketing Strategies and Tools', 'K. Swathini, L. Bhuvaneshwari, S. Gayathri', '978-93-47597-32-9', '1st Edition', 4, 'Digital marketing strategies use online channels to reach, engage, and convert audiences effectively. Key tools include SEO, content marketing, social media, email campaigns, PPC advertising, analytics, and marketing automation. These tools help target customers, track performance, personalize communication, and optimize campaigns, enabling businesses to increase visibility, drive traffic, generate leads, and improve overall brand growth.\n\n', 1126.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 203, '2026', '/uploads/books/1784549461164-Digital Marketing Strategies and Tools Swathini p1.png', '/uploads/books/1784549461201-Digital Marketing Strategies and Tools Swathini p2.png', NULL, '2026-07-20 12:11:01'),
(92, 'Mapping Post Colonial Studies : Contexts, Literary themes, Techniques & Present debates', 'Dr. Mandela N', '978-93-47597-88-6', '1st Edition', 5, 'Postcolonial studies examines the cultural, political, and literary impacts of colonialism and its lasting legacies. It explores themes like identity, hybridity, resistance, displacement, language, and power. Literary techniques include narration from marginalized voices, code-switching, and reinterpretation of history. Current debates address globalization, decolonization, representation, and the evolving voices of formerly colonized societies.\n\n', 1126.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 205, '2026', '/uploads/books/1784549574555-Mapping Post Colonial Studies  Mandela p1.png', '/uploads/books/1784549574565-Mapping Post Colonial Studies  Mandela p2.png', NULL, '2026-07-20 12:12:54'),
(93, 'Deep Learning in Computer Vision:Image Recognition and Beyond', 'V.Deepa, R.Sujitha', '978-93-47597-40-4', '1st Edition', 5, 'Deep learning has transformed computer vision by enabling accurate image recognition, object detection, segmentation, and facial analysis. Using convolutional neural networks and advanced architectures, systems learn visual patterns from large datasets. Beyond recognition, applications include autonomous vehicles, medical imaging, surveillance, augmented reality, and scene understanding, improving automation, precision, and real-time decision-making across industries.\n\n', 1013.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 186, '2026', '/uploads/books/1784549672053-Deep Learning in Computer Vision Deepa p1.png', '/uploads/books/1784549672068-Deep Learning in Computer Vision Deepa p2.png', NULL, '2026-07-20 12:14:32'),
(94, 'Foundation of Research: Methodology, Ethics and Philosophy', 'Dr.Priyanka Bansode', '978-93-47597-12-1', '1st Edition', 5, 'Foundations of research integrate methodology, ethics, and philosophy to guide systematic inquiry. Methodology defines research design, data collection, and analysis methods. Ethics ensures integrity, consent, confidentiality, and responsible conduct. Philosophy shapes assumptions about knowledge, reality, and reasoning. Together, they help researchers produce valid, reliable, and meaningful findings across academic and professional disciplines.\r\n\r\n', 1463.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 393, '2026', '/uploads/books/1784549783802-Foundation of Research Priyanka p1.png', '/uploads/books/1784549783813-Foundation of Research Priyanka p2.png', 'https://www.flipkart.com/product/p/itme?pid=9789347597121', '2026-07-20 12:16:23'),
(95, 'AI in Robotics: Concepts and Applications', 'Mr.Mahendiran C R', '978-93-47597-93-0', '1st Edition', 5, 'AI in robotics combines perception, learning, and decision-making to create autonomous machines. Using computer vision, machine learning, and sensors, robots understand environments, plan actions, and adapt dynamically. Applications include manufacturing, healthcare, logistics, agriculture, and exploration, improving precision, safety, efficiency, and collaboration through intelligent automation and real-time problem solving.\n\n', 1335.99, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 215, '2026', '/uploads/books/1784549880961-AI in Robotics, Concepts and Applications p1.png', '/uploads/books/1784549880976-AI in Robotics, Concepts and Applications p2.png', NULL, '2026-07-20 12:18:00'),
(96, 'Marketing Management and Consumer Behaviour', 'Dr. Akila S, Mrs Chaitrashree M R, Mrs. Anitha M, Mrs.vidya R', '978-93-47597-33-6', '1st Edition', 5, 'Marketing management focuses on planning, pricing, promotion, and distribution to deliver value and achieve organizational goals. Consumer behaviour examines how individuals decide what to buy, influenced by psychological, social, and cultural factors. Together, they guide market research, segmentation, targeting, positioning, branding, and relationship building to satisfy customers, build loyalty, and drive sustainable business growth.\n\n', 1013.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 185, '2026', '/uploads/books/1784549988077-Marketing-Management-and-Consumer-Behaviour-p1.png', '/uploads/books/1784549988088-Marketing-Management-and-Consumer-Behaviour-p2.png', NULL, '2026-07-20 12:19:48'),
(97, 'Data Structure and Algorithms', 'Dr. Akheel Mohammed, Dr. Gurrampally Kumar, A.Swamy Goud, S.Anusha', '978-93-47597-82-4', '1st Edition', 5, 'Data structures organize and store data efficiently, while algorithms define step-by-step procedures to solve problems. Together, they enable optimized searching, sorting, processing, and memory management. Concepts like arrays, linked lists, trees, graphs, hashing, recursion, and dynamic programming improve performance, scalability, and reliability, forming the foundation of efficient software development and computational problem solving.\n\n', 1226.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 207, '2026', '/uploads/books/1784550102467-Data Structure and Algorithms p1.png', '/uploads/books/1784550102479-Data Structure and Algorithms p2.png', NULL, '2026-07-20 12:21:42'),
(98, 'Deep Learning in Computer Vision: Image Recognition and Beyond', 'Dr. Arun .A', '978-93-47597-91-6', '1st Edition', 5, 'Deep learning in computer vision uses neural networks, especially CNNs and transformers, to interpret images and videos. It enables tasks like image classification, object detection, segmentation, tracking, and generation. Applications span healthcare, security, autonomous vehicles, retail, and media, delivering accurate perception, automation, and insights beyond traditional image recognition.\n\n', 1013.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 189, '2026', '/uploads/books/1784550315836-Deep Learning in Computer Vision Arun p1.png', '/uploads/books/1784550315848-Deep Learning in Computer Vision Arun p2.png', NULL, '2026-07-20 12:25:15'),
(99, 'Corporate Accounting Financial Statements Analysis & Research', 'Dr. Atul Kumar, Sowmya V, Chithra D, Dr. K. Pavan', '978-93-47597-79-4', '1st Edition', 5, 'Corporate accounting focuses on preparing and interpreting financial statements to assess organizational performance. Financial statement analysis uses ratios, trends, and cash flow evaluation to measure profitability, liquidity, solvency, and efficiency. Research methods support informed decision-making, risk assessment, compliance, and strategic planning, helping stakeholders understand financial health and drive sustainable business growth.\r\n\r\n', 1351.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 355, '2026', '/uploads/books/1784550426989-Corporate Accounting Atul Kumar p1.png', '/uploads/books/1784550426999-Corporate Accounting  Atul kumar p2.png', 'https://www.flipkart.com/product/p/itme?pid=9789347597794', '2026-07-20 12:27:07'),
(100, 'Fundamentals of Internet of Things', 'Dr.S.Parthiban', '978-93-47597-29-9', '1st Edition', 5, 'The Internet of Things connects physical devices through sensors, networks, and cloud platforms to collect and exchange data. It enables real-time monitoring, automation, and smart decision-making. Core concepts include embedded systems, communication protocols, data analytics, and security. Applications span smart homes, healthcare, industry, agriculture, and cities, improving efficiency, convenience, and operational intelligence.\n\n', 1238.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 262, '2026', '/uploads/books/1784550520603-Fundamentals of Internet of Things Parthiban p1.png', '/uploads/books/1784550520617-Fundamentals of Internet of Things Parthiban p2.png', NULL, '2026-07-20 12:28:40'),
(101, 'Development Economics', 'Dr. F. Merlin Kokila', '978-93-47597-92-3', '1st Edition', 5, 'Development Economics examines how low- and middle-income countries achieve sustainable economic growth and improved living standards. It analyzes poverty, inequality, unemployment, human capital, trade, and institutional reforms. The field explores policies promoting industrialization, financial inclusion, education, and technology adoption to foster inclusive development, reduce disparities, and enhance long-term economic resilience and prosperity.\r\n\r\n', 1226.00, 'In Stock', '320 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 215, '2026', '/uploads/books/1784550607711-Development Economics p1.png', '/uploads/books/1784550607725-Development Economics p2.png', 'https://www.flipkart.com/product/p/itme?pid=9789347597794', '2026-07-20 12:30:07'),
(185, 'People Analytics and Data-Driven Human Resource Management', 'Venkat HRD, Thangadurai, Varanasi Chinmoy, Pranya', '978-93-47597-71-8', '1st Edition', 5, 'Tracking KPIs and correlation data to see how training, management styles, and workplace culture impact overall output.', 1126.00, 'In Stock', '220 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 234, '2026', '/uploads/books/1784780289276-People Analytics and Data-Driven Human Resource Management p1.png', '/uploads/books/1784780289292-People Analytics and Data-Driven Human Resource Management p2.png', '', '2026-07-23 04:18:09'),
(186, 'Artificial Intelligence and Machine Learning', 'M. Chandraprabha, Dr. M. Manju, Dr. Meenakshi Dalal, Dr. Priyadeep', '978-81-69635-06-6', '1st Edition', 5, 'Artificial Intelligence (AI) and Machine Learning (ML) are transformative technologies that enable computers to perform tasks that typically require human intelligence. While AI focuses on creating intelligent systems capable of reasoning, decision-making, and problem-solving, Machine Learning is a subset of AI that allows these systems to learn from data, identify patterns, and improve their performance over time without explicit programming.', 1351.00, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 322, '2026', '/uploads/books/1784783691424-Artificial Intelligence and Machine Learning2 p1.png', '/uploads/books/1784783691454-Artificial Intelligence and Machine Learning2 p2.png', '', '2026-07-23 05:14:51'),
(187, 'Strategic Human Resource Management Concepts and Applications', 'Dr Keerthi BS, Dr. Wachyu Hari Haji, C Radhika Rani, Saranya P K', '978-81-69635-05-9', '1st Edition', 5, 'Understanding how HR serves as a strategic partner to executive leadership, helping drive competitive advantage, navigate mergers and acquisitions, and manage organizational change.', 1013.00, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 195, '2026', '/uploads/books/1784784113006-Strategic Human Resource Management Concepts and Applications p1.png', '/uploads/books/1784784113021-Strategic Human Resource Management Concepts and Applications p2.png', '', '2026-07-23 05:21:53'),
(188, 'Cryptography and Cyber Security', 'Dr. Fahim Khan, Mrs.K. Sangeetha, Saranya P K, Gajjala Ramya Sri', '978-81-69635-01-1', '1st Edition', 5, 'Cryptography and Cyber Security protect digital data through encryption and advanced security measures. They prevent cyber threats, ensure secure communication, safeguard privacy, maintain data integrity, and protect organizations from unauthorized access and cyberattacks.\n\n', 1126.00, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 192, '2026', '/uploads/books/1784784337386-Cryptography And Cyber Security p1.png', '/uploads/books/1784784337401-Cryptography And Cyber Security p2.png', '', '2026-07-23 05:25:37'),
(189, 'AI Applications to Electrical Engineering', 'Dr. Goturu Sreenivasan, Dr. Budi Srinivasa Rao, Dr. Besta Hariprasad, Dr. M.S.G. Smitha', '978-81-69635-66-0', '1st Edition', 5, 'AI Applications to Electrical Engineering explores the integration of artificial intelligence techniques in various aspects of electrical engineering, including automation, control systems, and smart grid technologies.\n\n', 1578.00, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 468, '2026', '/uploads/books/1784784759701-AI Applications to Electrical Engineering p1.png', '/uploads/books/1784784759745-AI Applications to Electrical Engineering p2.png', '', '2026-07-23 05:32:39'),
(190, 'Green Marketing', 'Dr. G. Ramanjaneyulu Dr. Satya Vani Bethapudi B. Venkata Lakshmi M. Umrez', '978-81-69635-02-8', '1st Edition', 5, 'Green Marketing explores the intersection of environmental sustainability and marketing strategies. It covers topics such as eco-friendly products, sustainable business practices, and consumer behavior towards green initiatives.\n\n', 1126.00, 'In Stock', '250 grams', 'Paperback', '7.0 x 9.4 inches', 'English', 'Single Color', 203, '2026', '/uploads/books/1784785282731-Green Marketing p1.png', '/uploads/books/1784785282766-Green Marketing p2.png', '', '2026-07-23 05:41:22');

