--
-- Table structure for table `conferences`
--

CREATE TABLE `conferences` (
  `id` int(11) NOT NULL,
  `conferencename` varchar(255) DEFAULT NULL,
  `conferencetitle` varchar(500) DEFAULT NULL,
  `isbn` varchar(500) DEFAULT NULL,
  `type` varchar(255) DEFAULT NULL,
  `about` text DEFAULT NULL,
  `dates` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`dates`)),
  `conferencestatus` varchar(500) DEFAULT NULL,
  `conferencesecurity` varchar(500) DEFAULT NULL,
  `conferencevalidity` varchar(500) DEFAULT NULL,
  `registerlink` varchar(500) DEFAULT NULL,
  `poster` varchar(500) DEFAULT NULL,
  `brochuredownload` varchar(500) DEFAULT NULL,
  `proceedingsdownload` varchar(500) DEFAULT NULL,
  `listenerparticipation` varchar(500) DEFAULT NULL,
  `certificatesdownload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `topics` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`topics`)),
  `fees` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`fees`)),
  `bankdetails` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`bankdetails`)),
  `speakers` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`speakers`)),
  `organizingcommittee` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`organizingcommittee`)),
  `advisorycommittee` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`advisorycommittee`)),
  `globalexperts` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`globalexperts`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

