INSERT INTO `conferences` (`id`, `conferencename`, `conferencetitle`, `isbn`, `type`, `about`, `dates`, `conferencestatus`, `conferencesecurity`, `conferencevalidity`, `registerlink`, `poster`, `brochuredownload`, `proceedingsdownload`, `listenerparticipation`, `certificatesdownload`, `topics`, `fees`, `bankdetails`, `speakers`, `organizingcommittee`, `advisorycommittee`, `globalexperts`, `created_at`) VALUES
(26, 'ICGMRFT – 2026', 'Global Multidisciplinary Research and Future Technologies', NULL, 'Virtual Conference', 'A global virtual platform bringing together researchers, academicians, and industry experts to discuss emerging trends. The conference aims to promote knowledge sharing and innovation-driven research addressing real-world challenges across Artificial Intelligence, Digital Transformation, and Sustainable Systems.', '{\"abstractSubmission\":\"2026-03-25\",\"fullPaperSubmission\":\"2026-03-27\",\"conferenceDate\":\"2026-03-31\"}', 'Fully Released', 'Public', 'March 2026 Edition', 'https://docs.google.com/forms/d/e/1FAIpQLSeuqe_HNK6o7oj3e4M-VCEKkWnTCEQtvsCZ9i5dMDWSc3UeTw/viewform?pli=1', '/assets/image/conference/ICGMRFT-31 Mar 2026.jpeg', '/assets/image/conferences/1783930792973-ICGMRFT-31 Mar 2026 (3).jpeg', '/assets/image/conferences/1783930792745-ICGMRFT-Fullpaper-31-Mar-2026-new.pdf', NULL, '[{\"name\":\"Track 01\",\"file\":\"/assets/image/conferences/1783930792986-ICGMRFT-Track-1-Certificate.pdf\"},{\"name\":\"Track 02\",\"file\":\"/assets/image/conferences/1783930792989-ICGMRFT-Track-2-Certificate.pdf\"},{\"name\":\"Track 03\",\"file\":\"/uploads/conferences/1783938748850-ICGMRFT-Track-3-Certificate.pdf\"}]', '[\"Artificial Intelligence and Intelligent Computing Systems\",\"Data Science, Big Data and Advanced Analytics\",\"Emerging Technologies: IoT, Blockchain and Cyber Security\",\"Cloud, Edge Computing and Digital Infrastructure\",\"Industry 5.0 and Smart Manufacturing Systems\",\"Sustainable Engineering and Renewable Energy\",\"Smart Cities and Infrastructure Innovation\",\"Innovation and Digital Business Transformation\",\"FinTech and Technology-Driven Management\",\"Multidisciplinary Research and Social Innovation\"]', '{\"academicians\":\"600\",\"student\":\"400\",\"researchScholars\":\"500\",\"listener\":\"300\"}', NULL, '[]', '[{\"role\":\"Convener\",\"name\":\"Dr. Baskar Kandasamy\",\"mobile\":\"+91 93448 10452\",\"email\":\"\"},{\"role\":\"Convener\",\"name\":\"Ms. C. Bharathi\",\"mobile\":\"+91 96009 21734\",\"email\":\"\"},{\"role\":\"Convener\",\"name\":\"Swetha Pandiyan\",\"mobile\":\"+91 77088 26908\",\"email\":\"\"}]', '[{\"name\":\"Dr. Shailendra Daf\",\"designation\":\"Co Dean - Mechanical Engg\",\"institution\":\"Priyadarshini Bhagwati College\",\"location\":\"Nagpur\",\"image\":null},{\"name\":\"Prof (Dr) Manoj Kumar Katual\",\"designation\":\"Principal - Pharmacy\",\"institution\":\"Florence College\",\"location\":\"Jharkhand\",\"image\":null,\"imageFile\":null}]', '[{\"name\":\"Prof. Dr. Priya Trivedi\",\"designation\":\"Principal | Botany\",\"institution\":\"Maa Narmada Mahavidyalaya Dhamnod\",\"location\":\"Madhya Pradesh, India\",\"image\":null},{\"name\":\"Vishal Dahiya\",\"designation\":\"Director | Computer Science\",\"institution\":\"Sardar Vallabhbhai Global University\",\"location\":\"Gujarat, India\",\"image\":null,\"imageFile\":null},{\"name\":\"Dr. S. Ranjana\",\"designation\":\"Assistant Professor | Data Science\",\"institution\":\"Anna Adarsh College for Women\",\"location\":\"Tamil Nadu, India\",\"image\":null},{\"name\":\"Bollini ManojKumar\",\"designation\":\"Assistant Professor | ECE\",\"institution\":\"Annamacharya Institute (AITS)\",\"location\":\"Andhra Pradesh, India\",\"image\":null},{\"name\":\"Dr. P. Vanajakshi\",\"designation\":\"Professor & Cluster Head | CSE\",\"institution\":\"Sapthagiri NPS University\",\"location\":\"Karnataka, India\",\"image\":null},{\"name\":\"Ananya Swain\",\"designation\":\"Assistant Professor | Economics & Finance\",\"institution\":\"ASTHA School of Management\",\"location\":\"Odisha, India\",\"image\":null}]', '2026-07-13 10:19:02'),
(27, 'ICETITMR – 2026', 'Emerging Trends in Innovation, Technology & Multidisciplinary Research', '978-934759757-2', 'Virtual Conference', 'The International Conference on Emerging Trends in Innovation, Technology & Multidisciplinary Research (ICETITMR – 2026) aims to promote academic excellence and industry-academia interaction while encouraging young researchers to contribute to emerging areas of science, engineering, management, and humanities.', '{\"abstractSubmission\":\"2026-02-23\",\"fullPaperSubmission\":\"2026-02-25\",\"conferenceDate\":\"2026-02-28\"}', 'Fully Released', 'Public', 'February 2026 Edition', NULL, '/assets/image/conference/ICETITMR-28-Feb-2026.jpeg', NULL, '/assets/image/conference/ICETITMR–28-Feb-2026.pdf', NULL, '[{\"name\":\"Conference Certificate\",\"file\":\"/assets/image/conference/ICETITMR-Conference.pdf\"}]', '[\"Artificial Intelligence, Machine Learning & Data Science\",\"Robotics, Automation & Internet of Things (IoT)\",\"Sustainable Development and Green Technologies\",\"Healthcare Technologies\",\"Emerging Engineering Technologies\",\"Innovation and Entrepreneurship\",\"Management and Business Studies\",\"Humanities and Social Sciences\",\"Digital Transformation\",\"Multidisciplinary Research\"]', '{\"academicians\":\"600\",\"student\":\"400\",\"researchScholars\":\"500\",\"listener\":\"300\"}', '{\"bankName\":\"HDFC Bank\",\"accountName\":\"Dr. K. Baskar\",\"accountNo\":\"50200107530199\",\"ifscCode\":\"HDFC0001588\",\"upiId\":\"coo.veritaz@okhdfcbank\"}', '[]', '[{\"role\":\"Convener\",\"name\":\"Mrs. Sangeetha Subramaniam\",\"mobile\":\"+91 9944304713\",\"email\":\"\"},{\"role\":\"Co-Convener\",\"name\":\"Dr. Baskar Kandasamy\",\"mobile\":\"+91 9344810452\",\"email\":\"\"},{\"role\":\"Co-Convener\",\"name\":\"Mrs. C. Bharathi\",\"mobile\":\"+91 9600921734\",\"email\":\"\"}]', '[{\"name\":\"Dr. R. Suganthi\",\"designation\":\"Professor - CS with Data Analytics\",\"institution\":\"Dr.N.G.P. Arts and Science College\",\"location\":\"Coimbatore, Tamil Nadu, India\",\"image\":null},{\"name\":\"Dr. S. Venkata Siva Kumar\",\"designation\":\"Associate Professor - IT\",\"institution\":\"Vardhaman College of Engineering\",\"location\":\"Telangana, India\",\"image\":null},{\"name\":\"Dr. Archana M. Kinagi\",\"designation\":\"Professor and Chairperson - MBA\",\"institution\":\"Sharnbasva University\",\"location\":\"Karnataka, India\",\"image\":null},{\"name\":\"Dr. Sandip Chandra\",\"designation\":\"Associate Professor - Commerce\",\"institution\":\"SEMCOM, The CVM University\",\"location\":\"Gujarat, India\",\"image\":null},{\"name\":\"Dr. Ankit Sharma\",\"designation\":\"Assistant Professor - Civil Engineering\",\"institution\":\"Jai Parkash Mukand Lal Institute\",\"location\":\"Radaur, Haryana, India\",\"image\":null},{\"name\":\"Dr. Prachee Sharma\",\"designation\":\"Assistant Professor - Economics\",\"institution\":\"ICFAI University\",\"location\":\"Chhattisgarh, India\",\"image\":null}]', '[]', '2026-07-13 10:19:02'),
(28, 'ICIRMD-2026', 'Innovation & Research in Multidisciplinary Domains', '978-93-47785-04-7', 'Virtual Conference', 'The International Conference on Innovation & Research in Multidisciplinary Domains (ICIRMD-2026) aims to bring together researchers, academicians, industry experts, and students from around the world to exchange knowledge, present cutting-edge research, and discuss innovative approaches across diverse multidisciplinary fields. The conference encourages interdisciplinary dialogue, collaboration, and networking to address contemporary challenges through innovation-driven research and development.', '{\"abstractSubmission\":null,\"fullPaperSubmission\":null,\"conferenceDate\":\"2026-01-31\"}', 'Fully Released', 'Public', 'January 2026 Edition', 'payment-Veritaz.php', '/assets/image/conference/ICIRMD-31-Jan-2026.jpeg', NULL, '/assets/image/conference/FullPaper-ICIRMD-31-Jan-2026.pdf', '/assets/image/conference/ICIRMD-31-Jan-26-Certificate-of-listener.pdf', '[{\"name\":\"Track 01\",\"file\":\"/assets/image/conference/ICIRMD-31-Jan-26-Certificate.pdf\"},{\"name\":\"Track 02\",\"file\":\"/assets/image/conference/ICIRMD-31-Jan-26-Certificate-2.pdf\"},{\"name\":\"Track 03\",\"file\":\"/assets/image/conference/ICIRMD-31-Jan-26-Certificate-3.pdf\"}]', '[\"Innovation in Multidisciplinary Research\",\"Engineering and Technology\",\"Artificial Intelligence and Machine Learning\",\"Data Science and Analytics\",\"Internet of Things (IoT)\",\"Healthcare and Biomedical Technologies\",\"Business Management and Entrepreneurship\",\"Education and Learning Technologies\",\"Sustainable Development\",\"Interdisciplinary Research\"]', '{\"academicians\":null,\"student\":null,\"researchScholars\":null,\"listener\":null}', NULL, '[{\"name\":\"Dr. R. ASOKAN\",\"designation\":\"Principal\",\"institution\":\"Kongunadu College of Engineering and Technology\",\"location\":\"Trichy, Tamil Nadu, India\",\"image\":\"/assets/image/conference/Asokan.png\"},{\"name\":\"Prof. Dr. Amol Mutrgai\",\"designation\":\"Professor, MBA\",\"institution\":\"SNJB\'s College of Engineering\",\"location\":\"Maharashtra, India\",\"image\":\"/assets/image/conference/Amol-Mutrgai.png\"},{\"name\":\"Dr. Chilukuri Bala Subbarayudu\",\"designation\":\"Professor & Head, EEE\",\"institution\":\"Shadan Women\'s College of Engineering\",\"location\":\"Telangana, India\",\"image\":\"/assets/image/conference/Chilukuri.png\"}]', '[{\"role\":\"Convener\",\"name\":\"Mrs. Sangeetha Subramaniam\",\"mobile\":\"+91 91235 50135\",\"email\":\"\"},{\"role\":\"Co-Convener\",\"name\":\"Dr. Baskar Kandasamy\",\"mobile\":\"+91 93448 10452\",\"email\":\"\"},{\"role\":\"Inquiry\",\"name\":\"Ms. C. Bharathi\",\"mobile\":\"+91 96009 21734\",\"email\":\"\"}]', '[{\"name\":\"Dr. Sougata Chattopadhyay\",\"designation\":\"Assistant Manager, Civil Engineering\",\"institution\":\"Beaver Infra Consultants\",\"location\":\"\",\"image\":null},{\"name\":\"Dr. A. Peter Soosai Anandaraj\",\"designation\":\"Professor & Head, Information Technology\",\"institution\":\"Veltech Rangarajan R&D Institute\",\"location\":\"\",\"image\":null},{\"name\":\"Dr. Kirtikumar L. Ekhande\",\"designation\":\"Principal\",\"institution\":\"Geetai Arts and Commerce College\",\"location\":\"\",\"image\":null},{\"name\":\"Dr. P. N. E. Naveen\",\"designation\":\"Professor, Mechanical Engineering\",\"institution\":\"NS Raju Institute\",\"location\":\"\",\"image\":null},{\"name\":\"Dr. Akheel Mohammed\",\"designation\":\"Associate Professor, AI & ML\",\"institution\":\"J B Institute\",\"location\":\"\",\"image\":null},{\"name\":\"Prof. Dhruva M. S.\",\"designation\":\"Associate Professor & Head, Computer Science\",\"institution\":\"BGS Institute of Technology\",\"location\":\"\",\"image\":null}]', '[]', '2026-07-13 10:19:02'),
(29, 'ICMARD-25', 'Multidisciplinary Advances in Research & Development', '978-93-47597-52-7', 'Virtual Conference', 'The International Conference on Multidisciplinary Advances in Research & Development (ICMARD-25) brings together scholars, industry experts, and innovators to share cutting-edge research across science, engineering, technology, social sciences, and management. The conference fosters cross-disciplinary collaboration, promotes knowledge exchange, and addresses global challenges through innovative methodologies and applications. It provides a platform for presenting papers, networking, and discussing emerging trends that drive sustainable development and impactful research outcomes worldwide.', '{\"abstractSubmission\":\"2025-12-15\",\"fullPaperSubmission\":\"2025-12-17\",\"conferenceDate\":\"2025-12-29\"}', 'Fully Released', 'Public', 'December 2025 Edition', 'mailto:info@veritazinternational.com', '/assets/image/conference/ICMARD-29-Dec-2025.jpeg', NULL, '/assets/image/conference/ICMARD-Conference-Paper-Dec-29.pdf', NULL, '[{\"name\":\"Presented Certificate\",\"file\":\"/assets/image/conference/ICMARD presented certificate.pdf\"}]', '[\"Healthcare & Artificial Intelligence\",\"Machine Learning for Disease Prediction\",\"Internet of Things (IoT) & Automation\",\"Industrial IoT and Smart Systems\",\"Agriculture Technology & Smart Farming\",\"Plant Disease Detection using AI\",\"Social Science & Humanities\",\"Digital Education and Learning\",\"Human Resource Management\",\"Multidisciplinary Research & Development\"]', '{\"academicians\":\"500\",\"student\":\"300\",\"researchScholars\":\"400\",\"listener\":null}', '{\"bankName\":\"HDFC Bank\",\"accountName\":\"Veritaz Int. Press\",\"accountNo\":\"50200107530199\",\"ifscCode\":\"HDFC0001588\"}', '[]', '[{\"role\":\"Convener\",\"name\":\"Mrs. Sangeetha Subramaniam\",\"mobile\":\"+91 9123550135\",\"email\":\"\"},{\"role\":\"Paper Submission\",\"name\":\"Dr. Baskar Kandasamy\",\"mobile\":\"+91 9629076711\",\