INSERT INTO `testimonials` (`id`, `name`, `designation`, `rating`, `avatar_url`, `is_video_testimonial`, `video_url`, `content`, `created_at`) VALUES
(1, 'Dr.A.Sheela', 'professor', 5, 'https://image2url.com/r2/default/images/1774936976076-0d7729f7-867e-4c0b-8b70-eb74128bc04e.png', 0, NULL, 'This book is very helpful for students. The topics are explained clearly . The presentation is neat and systematic manner.The book is very informative and well written mam.Thank you for Pencil bitz team', '2026-07-13 11:55:44'),
(2, 'Saurabh Raut', 'professor', 5, 'https://image2url.com/r2/default/images/1774936258877-760cff73-b24b-4170-bebb-1577b588b8a3.png', 0, NULL, 'I am extremely pleased with the overall publication process and the professional support provided by the team. The editorial guidance was clear, timely, and highly constructive throughout. The quality of printing, formatting, and presentation has exceeded my expectations. Communication was smooth and responsive at every stage of publication. I truly appreciate the dedication and attention given to my work. This experience has been both encouraging and motivating for my future writing. I look forward to collaborating again in the future.', '2026-07-13 11:55:44'),
(3, 'Dr.Bharani Sethu Pandian', 'professor', 5, 'https://image2url.com/r2/default/images/1774936578125-ba5a0cb5-5c71-43c4-bec5-e74b56c48811.png', 0, NULL, 'Veritaz International Press is a full-service publishing company offering expert editorial, design, printing, and digital publishing solutions. We serve authors, businesses, and institutions with high-quality, timely, and cost-effective publishing services. Our mission is to empower voices and deliver impactful content across print and digital platforms.', '2026-07-13 11:55:44'),
(4, 'Dr.Subash', 'professor', 5, 'https://image2url.com/r2/default/images/1774936757158-426fa4c9-0981-43e7-b359-3f901bf4201b.png', 0, NULL, 'Veritaz International Press is a full-service publishing company offering expert editorial, design, printing, and digital publishing solutions. We serve authors, businesses, and institutions with high-quality, timely, and cost-effective publishing services. Our mission is to empower voices and deliver impactful content across print and digital platforms.', '2026-07-13 11:55:44'),
(5, 'Dr. Arun .A', 'professor', 5, 'https://pub-1407f82391df4ab1951418d04be76914.r2.dev/uploads/26a2e57c-82eb-4843-981d-a618ab01b1cc.png', 1, 'assets/image/Testmonoials/Arun.mp4', 'Working with Veritaz International Press has been a truly collaborative and rewarding experience. I was impressed by the professionalism and efficiency of the publishing team throughout this process. From the initial acquisition to the final layout, their team demonstrated a high level of expertise and dedication. The support staff’s Aswathi & Deva Shree were always responsive and helpful whenever I had queries. It has been a seamless collaboration till the final print.', '2026-07-13 11:55:44');

